private final class StudioResizeHandle: NSView {
    enum Axis { case horizontal, vertical }; let axis: Axis; var dragged: ((CGFloat)->Void)?; private var lastPoint:NSPoint?
    init(axis:Axis){self.axis=axis;super.init(frame:.zero);wantsLayer=true}; required init?(coder:NSCoder){fatalError()}
    override func resetCursorRects(){addCursorRect(bounds,cursor:axis == .vertical ? .resizeLeftRight:.resizeUpDown)}
    override func mouseDown(with event:NSEvent){lastPoint=event.locationInWindow}
    override func mouseDragged(with event:NSEvent){guard let p=lastPoint else{return};let n=event.locationInWindow;let d=axis == .vertical ? n.x-p.x:n.y-p.y;lastPoint=n;dragged?(d)}
}
private final class StudioLayoutState { static let shared=StudioLayoutState(); var leftWidth:CGFloat=330;var rightWidth:CGFloat=350;var arrangementFraction:CGFloat=0.58;weak var leftHandle:StudioResizeHandle?;weak var rightHandle:StudioResizeHandle?;weak var horizontalHandle:StudioResizeHandle? }

private final class LiveArrangementView: NSView {
    var tracks:[EngineTrack]=[]; var clips:[EngineClip]=[]; var selectedTrackID:Int?; var selectedClipID:Int?; var onSelectTrack:((Int)->Void)?; var onSelectClip:((Int,Int)->Void)?
    override var isFlipped:Bool{true}
    override func draw(_ dirtyRect:NSRect){
        NSColor.csArrangement.setFill();bounds.fill();let header:CGFloat=170,top:CGFloat=34
        NSColor.csPanelStrong.setFill();NSRect(x:0,y:0,width:header,height:bounds.height).fill()
        NSColor.csTop.setFill();NSRect(x:header,y:0,width:max(0,bounds.width-header),height:top).fill()
        let maxBeat=max(16.0,clips.map{$0.startBeat+$0.lengthBeats}.max() ?? 16.0);let beatW=max(10,(bounds.width-header-12)/CGFloat(maxBeat))
        for b in stride(from:0,through:Int(ceil(maxBeat)),by:4){let x=header+CGFloat(b)*beatW;NSColor.csLine.setStroke();let p=NSBezierPath();p.move(to:NSPoint(x:x,y:top));p.line(to:NSPoint(x:x,y:bounds.height));p.stroke();("\(b+1)" as NSString).draw(at:NSPoint(x:x+3,y:8),withAttributes:[.font:NSFont.systemFont(ofSize:11),.foregroundColor:NSColor.secondaryLabelColor])}
        let n=max(1,tracks.count),rowH=max(46,(bounds.height-top)/CGFloat(n))
        for (i,t) in tracks.enumerated(){let y=top+CGFloat(i)*rowH;if t.id==selectedTrackID{NSColor.selectedContentBackgroundColor.withAlphaComponent(0.12).setFill();NSRect(x:0,y:y,width:bounds.width,height:rowH).fill()};("\(i+1)  \(t.name)" as NSString).draw(in:NSRect(x:12,y:y+14,width:header-20,height:22),withAttributes:[.font:NSFont.systemFont(ofSize:13,weight:.semibold),.foregroundColor:NSColor.csText]);NSColor.csLine.setStroke();let l=NSBezierPath();l.move(to:NSPoint(x:0,y:y+rowH));l.line(to:NSPoint(x:bounds.width,y:y+rowH));l.stroke()
            for c in clips where c.trackId==t.id {let x=header+CGFloat(c.startBeat)*beatW,w=max(8,CGFloat(c.lengthBeats)*beatW);let r=NSRect(x:x,y:y+7,width:min(w,bounds.width-x-4),height:rowH-14);NSColor.systemBlue.withAlphaComponent(c.id==selectedClipID ? 0.42:0.24).setFill();NSBezierPath(roundedRect:r,xRadius:5,yRadius:5).fill();if c.id==selectedClipID{NSColor.systemBlue.setStroke();let q=NSBezierPath(roundedRect:r,xRadius:5,yRadius:5);q.lineWidth=2;q.stroke()};for note in c.notes.prefix(300){let nx=x+CGFloat(note.startBeat)*beatW,nw=max(2,CGFloat(note.lengthBeats)*beatW);let pitch=CGFloat(127-note.note)/127;let ny=r.minY+3+pitch*max(1,r.height-8);NSColor.systemBlue.setFill();NSRect(x:nx,y:ny,width:min(nw,max(1,r.maxX-nx)),height:2).fill()}}
        }
        if tracks.isEmpty{("Keine Spuren – MIDI importieren oder + drücken" as NSString).draw(in:NSRect(x:header+24,y:top+28,width:420,height:28),withAttributes:[.font:NSFont.systemFont(ofSize:15,weight:.medium),.foregroundColor:NSColor.secondaryLabelColor])}
    }
    override func mouseDown(with event:NSEvent){let p=convert(event.locationInWindow,from:nil),header:CGFloat=170,top:CGFloat=34;guard p.y>=top,!tracks.isEmpty else{return};let rowH=max(46,(bounds.height-top)/CGFloat(max(1,tracks.count))),i=min(tracks.count-1,max(0,Int((p.y-top)/rowH))),t=tracks[i];selectedTrackID=t.id;if p.x>header{let maxBeat=max(16.0,clips.map{$0.startBeat+$0.lengthBeats}.max() ?? 16.0),beatW=max(10,(bounds.width-header-12)/CGFloat(maxBeat)),beat=Double((p.x-header)/beatW);if let c=clips.first(where:{$0.trackId==t.id && beat >= $0.startBeat && beat <= $0.startBeat+$0.lengthBeats}){selectedClipID=c.id;onSelectClip?(t.id,c.id)}};onSelectTrack?(t.id);needsDisplay=true}
}

private final class LivePianoRollView:NSView {
    var notes:[EngineMidiNote]=[];var title="Keine MIDI-Auswahl";override var isFlipped:Bool{true}
    override func draw(_ dirtyRect:NSRect){NSColor.csEditor.setFill();bounds.fill();(title as NSString).draw(at:NSPoint(x:10,y:7),withAttributes:[.font:NSFont.systemFont(ofSize:13,weight:.semibold),.foregroundColor:NSColor.csText]);guard !notes.isEmpty else{("Keine MIDI-Noten" as NSString).draw(at:NSPoint(x:60,y:48),withAttributes:[.font:NSFont.systemFont(ofSize:14),.foregroundColor:NSColor.secondaryLabelColor]);return};let minN=notes.map{$0.note}.min()!,maxN=notes.map{$0.note}.max()!,span=max(12,maxN-minN+1),maxBeat=max(4.0,notes.map{$0.startBeat+$0.lengthBeats}.max() ?? 4.0),left:CGFloat=48,top:CGFloat=30,bw=max(8,(bounds.width-left-8)/CGFloat(maxBeat)),rh=max(4,(bounds.height-top-8)/CGFloat(span));for n in notes{let x=left+CGFloat(n.startBeat)*bw,y=top+CGFloat(maxN-n.note)*rh,w=max(3,CGFloat(n.lengthBeats)*bw);NSColor.systemGreen.setFill();NSBezierPath(roundedRect:NSRect(x:x,y:y,width:min(w,bounds.width-x-4),height:max(3,rh-1)),xRadius:2,yRadius:2).fill()}}
}

private final class LiveStudioState { static let shared=LiveStudioState();let arrangement=LiveArrangementView();let piano=LivePianoRollView();var selectedTrackID:Int?;var selectedClipID:Int?;var importButton:NSButton?;var installed=false }

extension StudioViewController {
    func installEngineBindings(engineReady:Bool){let e=CompositionStudioEngine.shared;playButton.target=self;playButton.action=#selector(enginePlayPause);stopButton.target=self;stopButton.action=#selector(engineStop);recordButton.target=self;recordButton.action=#selector(engineRecord);installReadableTypography();installResizablePanes();installLiveDAW();if let f=transportCard.subviews.compactMap({$0 as? NSTextField}).first(where:{$0.identifier?.rawValue=="tempo"}){f.isEditable=true;f.isSelectable=true;f.target=self;f.action=#selector(engineTempoChanged(_:))};if let b=transportCard.subviews.compactMap({$0 as? NSButton}).first(where:{$0.title.contains("Metronom")}){b.target=self;b.action=#selector(engineMetronome(_:))};if let b=transportCard.subviews.compactMap({$0 as? NSButton}).first(where:{$0.identifier?.rawValue=="open"}){b.target=self;b.action=#selector(engineOpenProject)};if let b=transportCard.subviews.compactMap({$0 as? NSButton}).first(where:{$0.identifier?.rawValue=="save"}){b.target=self;b.action=#selector(engineSaveProject)};statusLabel.stringValue=engineReady ? "Bereit":"Audio-Engine Fehler";refreshEngineUI()}
    private func installLiveDAW(){let s=LiveStudioState.shared;guard !s.installed else{return};s.installed=true;arrangement.isHidden=true;pianoRoll.isHidden=true;arrangementCard.addSubview(s.arrangement);inspectorCard.addSubview(s.piano);s.arrangement.onSelectTrack={[weak self] id in s.selectedTrackID=id;self?.syncLiveDAW()};s.arrangement.onSelectClip={[weak self] tid,cid in s.selectedTrackID=tid;s.selectedClipID=cid;self?.syncLiveDAW()};if let plus=arrangementCard.subviews.compactMap({$0 as? NSButton}).first(where:{$0.identifier?.rawValue=="arrPlus"}){plus.target=self;plus.action=#selector(engineAddTrack)};if let minus=arrangementCard.subviews.compactMap({$0 as? NSButton}).first(where:{$0.identifier?.rawValue=="arrMinus"}){minus.target=self;minus.action=#selector(engineRemoveTrack)};let imp=NSButton(title:"MIDI importieren",target:self,action:#selector(engineImportMIDI));styleButton(imp,strong:true);arrangementCard.addSubview(imp);s.importButton=imp
        // Attrappen konsequent ausblenden, bis echte Implementierungen existieren.
        chatCard.isHidden=true;browserList.isHidden=true;browserButtons.forEach{$0.isHidden=true};browserTitle.stringValue="Plugins: noch nicht angebunden";inspectorButtons.forEach{$0.isHidden=true};inspectorCard.subviews.filter{$0.identifier?.rawValue.hasPrefix("chain_")==true || $0.identifier?.rawValue.hasPrefix("editor_")==true}.forEach{$0.isHidden=true};syncLiveDAW()}
    private func syncLiveDAW(){let e=CompositionStudioEngine.shared,s=LiveStudioState.shared;guard e.isReady else{return};let ts=e.tracks(),cs=e.clips();if s.selectedTrackID==nil || !ts.contains(where:{$0.id==s.selectedTrackID}){s.selectedTrackID=ts.first?.id};if s.selectedClipID != nil && !cs.contains(where:{$0.id==s.selectedClipID}){s.selectedClipID=nil};s.arrangement.tracks=ts;s.arrangement.clips=cs;s.arrangement.selectedTrackID=s.selectedTrackID;s.arrangement.selectedClipID=s.selectedClipID;s.arrangement.needsDisplay=true;if let t=ts.first(where:{$0.id==s.selectedTrackID}){inspectorTitle.stringValue="Spur: \(t.name)"}else{inspectorTitle.stringValue="Keine Spur"};if let c=cs.first(where:{$0.id==s.selectedClipID}){s.piano.notes=c.notes;s.piano.title="MIDI-Clip · \(c.notes.count) Noten"}else{s.piano.notes=[];s.piano.title="Keine MIDI-Auswahl"};s.piano.needsDisplay=true}
    @objc private func engineAddTrack(){let id=CompositionStudioEngine.shared.createTrack(name:"MIDI Spur \(CompositionStudioEngine.shared.tracks().count+1)");if id>=0{LiveStudioState.shared.selectedTrackID=id;statusLabel.stringValue="Spur angelegt"};syncLiveDAW()}
    @objc private func engineRemoveTrack(){guard let id=LiveStudioState.shared.selectedTrackID else{return};CompositionStudioEngine.shared.deleteTrack(id:id);LiveStudioState.shared.selectedTrackID=nil;LiveStudioState.shared.selectedClipID=nil;statusLabel.stringValue="Spur gelöscht";syncLiveDAW()}
