    private func installReadableTypography(){func enlarge(_ r:NSView){for v in r.subviews{if let f=v as? NSTextField,let font=f.font{f.font=.systemFont(ofSize:max(font.pointSize+2,13))}else if let b=v as? NSButton{b.font=.systemFont(ofSize:13,weight:.medium)};enlarge(v)}};enlarge(view);timeLabel.font=.monospacedDigitSystemFont(ofSize:19,weight:.semibold);inspectorTitle.font=.systemFont(ofSize:15,weight:.bold);playButton.font=.systemFont(ofSize:20,weight:.bold);stopButton.font=.systemFont(ofSize:18,weight:.bold);recordButton.font=.systemFont(ofSize:20,weight:.bold)}
    private func installResizablePanes(){let s=StudioLayoutState.shared;guard s.leftHandle==nil else{return};let l=StudioResizeHandle(axis:.vertical),r=StudioResizeHandle(axis:.vertical),h=StudioResizeHandle(axis:.horizontal);view.addSubview(l);view.addSubview(r);view.addSubview(h);s.leftHandle=l;s.rightHandle=r;s.horizontalHandle=h;l.dragged={[weak self]d in s.leftWidth=min(520,max(260,s.leftWidth+d));self?.applyResizableLayout()};r.dragged={[weak self]d in s.rightWidth=min(520,max(270,s.rightWidth-d));self?.applyResizableLayout()};h.dragged={[weak self]d in guard let self else{return};let u=max(1,self.arrangementCard.frame.height+self.inspectorCard.frame.height);s.arrangementFraction=min(.78,max(.38,s.arrangementFraction+d/u));self.applyResizableLayout()}}
    private func applyResizableLayout(){let s=StudioLayoutState.shared,W=view.bounds.width,H=view.bounds.height,m:CGFloat=8,g:CGFloat=7,topH:CGFloat=50,trH:CGFloat=72,contentTop=m+topH+g,bottomY=H-m-trH;let leftW:CGFloat=chatCard.isHidden ? 0:min(s.leftWidth,W*.32),rightW=min(s.rightWidth,W*.32),centerX=m+leftW+(leftW>0 ? g:0),centerW=max(520,W-2*m-leftW-rightW-(leftW>0 ? 2*g:g)),centerH=max(400,bottomY-contentTop-g),arrH=max(250,min(centerH-190,centerH*s.arrangementFraction));topBar.frame=NSRect(x:m,y:m,width:W-2*m,height:topH);chatCard.frame=NSRect(x:m,y:contentTop,width:leftW,height:centerH);arrangementCard.frame=NSRect(x:centerX,y:contentTop,width:centerW,height:arrH);inspectorCard.frame=NSRect(x:centerX,y:contentTop+arrH+g,width:centerW,height:centerH-arrH-g);browserCard.frame=NSRect(x:centerX+centerW+g,y:contentTop,width:rightW,height:centerH);transportCard.frame=NSRect(x:m,y:bottomY,width:W-2*m,height:trH);s.leftHandle?.isHidden=chatCard.isHidden;s.leftHandle?.frame=NSRect(x:m+leftW-3,y:contentTop,width:10,height:centerH);s.rightHandle?.frame=NSRect(x:centerX+centerW-3,y:contentTop,width:10,height:centerH);s.horizontalHandle?.frame=NSRect(x:centerX,y:contentTop+arrH-3,width:centerW,height:10);layoutTop();layoutBrowser();layoutInspector();layoutTransport();let live=LiveStudioState.shared;live.arrangement.frame=NSRect(x:8,y:42,width:arrangementCard.bounds.width-16,height:arrangementCard.bounds.height-50);live.importButton?.frame=NSRect(x:14,y:9,width:126,height:30);live.piano.frame=NSRect(x:178,y:38,width:max(100,inspectorCard.bounds.width-190),height:max(70,inspectorCard.bounds.height-48));enlargeTransportControls()}
    private func enlargeTransportControls(){let w=transportCard.bounds.width,y:CGFloat=10;stopButton.frame=NSRect(x:w*.46-62,y:y,width:48,height:48);playButton.frame=NSRect(x:w*.46-5,y:y-3,width:54,height:54);recordButton.frame=NSRect(x:w*.46+58,y:y-3,width:54,height:54);timeLabel.frame=NSRect(x:w*.20,y:20,width:135,height:30);transportCard.subviews.first{$0.identifier?.rawValue=="open"}?.frame=NSRect(x:w-196,y:18,width:82,height:34);transportCard.subviews.first{$0.identifier?.rawValue=="save"}?.frame=NSRect(x:w-106,y:18,width:92,height:34)}
    func refreshEngineUI(){applyResizableLayout();let e=CompositionStudioEngine.shared;guard e.isReady else{return};playButton.title=e.isPlaying ? "❚❚":"▶";statusLabel.stringValue=e.isRecording ? "Aufnahme":(e.isPlaying ? "Wiedergabe":"Bereit");let x=max(0,e.positionSeconds),mi=Int(x)/60,se=Int(x)%60,ms=Int((x-floor(x))*1000);timeLabel.stringValue=String(format:"%02d:%02d.%03d",mi,se,ms);if let f=transportCard.subviews.compactMap({$0 as? NSTextField}).first(where:{$0.identifier?.rawValue=="tempo"}),f.currentEditor()==nil{f.stringValue=String(format:"Tempo\n%.2f",e.tempo)};syncLiveDAW()}
