    @objc private func engineTempoChanged(_ f:NSTextField){let s=f.stringValue.replacingOccurrences(of:"Tempo",with:"").replacingOccurrences(of:"\n",with:"").trimmingCharacters(in:.whitespacesAndNewlines).replacingOccurrences(of:",",with:".");if let v=Double(s){CompositionStudioEngine.shared.setTempo(v)};refreshEngineUI()};@objc private func engineMetronome(_ b:NSButton){let e=CompositionStudioEngine.shared;e.setMetronome(!e.isMetronomeEnabled);refreshEngineUI()}
    @objc private func engineSaveProject(){let p=NSSavePanel();if let t=UTType(filenameExtension:"mgd"){p.allowedContentTypes=[t]};p.nameFieldStringValue=model.projectName+".mgd";guard let w=view.window else{return};p.beginSheetModal(for:w){[weak self]r in guard r == .OK,let u=p.url,let self else{return};self.statusLabel.stringValue=CompositionStudioEngine.shared.saveProject(as:u.path) ? "Projekt gespeichert":"Speichern fehlgeschlagen"}}
    @objc private func engineOpenProject(){let p=NSOpenPanel();if let t=UTType(filenameExtension:"mgd"){p.allowedContentTypes=[t]};guard let w=view.window else{return};p.beginSheetModal(for:w){[weak self]r in guard r == .OK,let u=p.url,let self else{return};if CompositionStudioEngine.shared.loadProject(from:u.path){self.model.projectName=u.deletingPathExtension().lastPathComponent;self.projectLabel.stringValue="Projekt: \(self.model.projectName)";LiveStudioState.shared.selectedTrackID=nil;LiveStudioState.shared.selectedClipID=nil;self.syncLiveDAW();self.statusLabel.stringValue="Projekt geladen"}else{self.statusLabel.stringValue="Laden fehlgeschlagen"}}}
